        $('input[name="lpContrtStrtDd"]').val('<c:out value="' + dma_readDataVO.get("lpContrtStrtDd") + '" escapeXml="true" />');
        $('input[name="lpContrtEndDd"]').val('<c:out value="' + dma_readDataVO.get("lpContrtEndDd") + '" escapeXml="true" />');
    } else {
        $('input[name="lpContrtStrtDd"]').val('');
        $('input[name="lpContrtEndDd"]').val('');
    }
};

