 */
scwin.insertComma = function (tab) {

    scwin.form = (document.digitalListForm || { elements: [] });
    const elem = scwin.form.elements;

    if(tab === 1) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('listQty') >= 0 ||
                elem[i].name.indexOf('pubofrAmt') >= 0 ||
                elem[i].name.indexOf('listAmt') >= 0 ||
                elem[i].name.indexOf('addIsuPrc') >= 0 ||
                elem[i].name.indexOf('addListRnd') >= 0 ||
                elem[i].name.indexOf('dutyHdCnt') >= 0
            )

            fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 2) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
